INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 14, 'theory', 'Quiz: persistent network configuration');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 14, 0, 'You ran ip addr add 10.0.0.5/24 dev eth0, and after a reboot the address is gone. Why?', '["ip writes the address to a temporary file in /tmp", "The address lives only in the kernel''s in-memory state; persistence comes from files and a service such as NetworkManager or networkd", "cron deletes addresses set with ip at boot", "An address can only be saved with the ifconfig command"]', 1, 'ip changes the kernel''s state directly, and at boot the kernel starts empty. For the setting to return, a service must read the configuration from disk.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 14, 1, 'In /etc/netplan there are 50-a.yaml with addresses: [10.0.0.5/24] and 60-b.yaml with addresses: [10.0.0.6/24] for the same card. What happens?', '["Only 10.0.0.6/24 remains, the later file replaces the list", "Only 10.0.0.5/24 remains, the first file wins", "The lists are concatenated: the card gets both addresses", "Netplan refuses to work with two files"]', 2, 'Netplan overwrites scalars but concatenates lists, with new items appended to the old list. To replace a list entirely you can only put a file of the same name into a higher-priority directory.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 14, 2, 'Two files match an interface at once: 10-wired.network and 20-all.network. What will systemd-networkd do?', '["Merge the settings of both files", "Apply the last file alphabetically", "Report a conflict error", "Apply only 10-wired.network and ignore the rest"]', 3, 'The first matching file in alphabetical order is applied and the rest are ignored even if they match. That is why general rules go into files with higher numbers.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 14, 3, 'You ran netplan try over SSH, the new setup cut your session, and you pressed nothing. What happens?', '["After the timeout (120 seconds by default) the configuration rolls back by itself", "The new configuration stays forever", "The server reboots", "Netplan waits for confirmation forever"]', 0, 'If there is no confirmation in the allotted time, netplan try restores the previous configuration. That is why it is used for remote changes; after a rollback, check that the network really came back.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 14, 4, 'You put a profile in /etc/NetworkManager/system-connections with mode 0644, and NetworkManager does not show it. What is the most likely cause?', '["The profile must go into /etc/sysconfig", "The file is accessible to others than root and the manager ignores it; it needs mode 0600", "The manager reads files only after a server reboot", "The file extension must be .conf"]', 1, 'A profile may contain secrets, so the manager ignores a file accessible to anyone but root. After fixing the mode and hand edits, run nmcli connection reload.');
